var w, h;

var clrBG = "#111";

var fb_ralph, fb_josh, fb_rob, fb_metamere, fb_jbuzza, fb_epi;

var framebuffers = {
  raph: null,
  josh: null,
  rob: null,
  metamere: null,
  jbuzza: null,
  epi: null,
};

var layer_opacity = 30;

function setup() {
  createCanvas((W = windowWidth), (H = windowHeight), WEBGL);
  w = W / 2;
  h = H / 2;

  // initialize framebuffers
  for (let fb in framebuffers) {
    framebuffers[fb] = createFramebuffer({ format: FLOAT });
  }

  fb_ralph = createFramebuffer({ format: FLOAT });
  fb_josh = createFramebuffer({ format: FLOAT });
  fb_rob = createFramebuffer({ format: FLOAT });
  fb_metamere = createFramebuffer({ format: FLOAT });
  fb_jbuzza = createFramebuffer({ format: FLOAT });
  fb_epi = createFramebuffer({ format: FLOAT });

  colorMode(HSB, 100, 100, 100, 100);
  t = 0;
}

function draw() {
  t += 0.01;
  background(clrBG);

  fb_ralph.begin();
  raph(fb_ralph);
  fb_ralph.end();

  fb_josh.begin();
  josh(fb_josh);
  fb_josh.end();

  fb_rob.begin();
  rob(fb_rob);
  fb_rob.end();

  fb_metamere.begin();
  metamere(fb_metamere);
  fb_metamere.end();

  fb_jbuzza.begin();
  jbuzza(fb_jbuzza);
  fb_jbuzza.end();

  fb_epi.begin();
  epi(fb_epi);
  fb_epi.end();

  // push();
  // tint(100, layer_opacity);
