  // image(fb_metamere, -width / 2, -height / 2);
  // image(fb_jbuzza, -width / 2, -height / 2);
  // image(fb_epi, -width / 2, -height / 2);
  // pop();

  // Number of images
  let numImages = 4;
  // Width of each stripe
  let stripeWidth = map(cos(millis() / 100.0),-1,1,20,width/numImages);
  let stripeHeight = map(sin(millis() / 100.0),-1,1,20,height);

  push();
  // tint(100, layer_opacity);
  translate(-width/2, -height / 2);

	/*
  // Draw each image within its respective stripe
  image(fb_ralph, 0, 0, stripeWidth, stripeHeight);
  // image(fb_josh, stripeWidth, 0, stripeWidth, stripeHeight);
  // image(fb_rob, 2 * stripeWidth, 0, stripeWidth, stripeHeight);
  image(fb_metamere, stripeWidth, 0, stripeWidth*2, stripeHeight);
  image(fb_jbuzza, 3 * stripeWidth, 0, stripeWidth*2, stripeHeight);
  image(fb_epi, 5 * stripeWidth, 0, stripeWidth, stripeHeight);
	*/

	// added by epi
	let fbStart = [], fbWidth = [];
	let images = [fb_ralph, fb_metamere, fb_jbuzza, fb_epi];
	for (let i = 0, a = frameCount * 0.0123; i < numImages; i++, a+= TWO_PI / numImages) {
		fbWidth[i] = w * (sin(a) + 1) / 2;
		if (i === 0) {
			fbStart[i] = 0;
		} else {
			fbStart[i] = fbWidth[i - 1] - fbStart[i - 1];
		}
		image(images[i], fbStart[i], 0, fbWidth[i], H);
	}

  pop();
}

function raph(fb) {
  //   push();
  // noStroke();

  fill(frameCount % 100, 100, 100, 30);

  let x = random(-w, w);
  let y = random(-h, h);

  translate(x, y);
  rotateX(frameCount / (100 %x));
  scale(sin(frameCount / 100) * 2 + 1);
  box(100, 100, 100);
  //   pop();
}

function josh(fb) {}

function rob(fb) {}

function metamere(fb) {
  push();
  scale(4+abs(sin(t/16)),1+abs(sin(t/24)))
  rotate(t + Math.random()/10);
  fill(t % 100, 95, 95, 50);
  strokeWeight(2);
  stroke(0, 30);
  rect(0, 0, w * abs(sin(t * 32)));
  pop();
}

function jbuzza(fb) {
  push();
  colorMode(HSB, 100, 100, 100, 100);
  strokeWeight(5);
  stroke(random(100), random(50,100), random(50,100), 20);
  var x_star = random(-width, width);
  var y_star = random(-height, height);
  var w_star = random(width / 12, width / 6);
  var h_star = random(height / 12, height / 6);
  generateStar(x_star, y_star, w_star, h_star);
  pop();

  function generateStar(x_star, y_star, w_star, h_star) {
    let d = 0;
    let symmetry = 8;

    do {
      var x1 = random(w_star) - w_star / 2;
      var y1 = random(h_star) - h_star / 2;
      var x2 = random(w_star) - w_star / 2;
      var y2 = random(h_star) - h_star / 2;
      d = dist(x1, y1, x2, y2);
    } while (d < w_star / 2);

    let angle = 360 / symmetry;

    translate(x_star, y_star);

    for (let i = 0; i < symmetry; i++) {
      rotate(angle);
      line(x1, y1, x2, y2);
      push();
      scale(-1, 1);
      line(x1, y1, x2, y2);
      pop();
    }
  }
}

function epi(fb) {
  if (frameCount === 1) {
		background("lightblue");
    epi_stars = [];
    for (let i = 0; i < 100; i++) {
      epi_stars.push({ x: random(-w, w), y: random(-h, h), s: random(222) });
    }
  }

  push();
  fill(45+noise(frameCount * 0.0512) * 45, 75, 75, 25);
  noStroke();
  const x1 = noise(frameCount * 0.0121) * 2 * W - W;
  const y1 = noise(frameCount * 0.0213) * 2 * H - H;
  const x2 = noise(frameCount * 0.0321) * 2 * W - W;
  const y2 = noise(frameCount * 0.0313) * 2 * H - H;
  const x3 = noise(frameCount * 0.0421) * 2 * W - W;
  const y3 = noise(frameCount * 0.0413) * 2 * H - H;
  triangle(x1, y1, x2, y2, x3, y3);

  // for (let star of epi_stars) {
  for (let i = 0; i < epi_stars.length; i++) {
    star = epi_stars[i];
    fill(abs(star.x) % 15, 75, 75, 25 - 2*sqrt(star.s));
    circle(star.x*=1.002, star.y*=1.002, star.s*=1.05);
    if (random()<0.05 || star.s > 255) {
      epi_stars[i] = { x: random(-w, w), y: random(-h, h), s: 1 }
      star.x= random(-w, w)
      star.y= random(-h, h)
      star.s= 1 
    }
  }

  if (random()<0.1) {
    const maxWH = random(max(w*0.1,h*0.1), min(w*0.65,h*0.65));
    let part = get(floor(random(-w,w)),floor(random(-h,h)),maxWH, maxWH);
    blendModeimage(part, floor(random(-w,w)),floor(random(-h,h)));
    blendMode(BLEND)
  }
}
